import{c as a,Q as e,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"我连续跑了几个月 Hermes Agent，最后发现：99% 的人根本没用对 AI Agent","description":"","frontmatter":{"url":"https://x.com/0xluffy_eth/status/2061641905096790310","title":"我连续跑了几个月 Hermes Agent，最后发现：99% 的人根本没用对 AI Agent","author":"0xluffy_eth","archived":"2026-06-02T00:00:00.000Z","handle":"@0xluffy_eth","published":"2026-06-02T00:00:00.000Z","stats":"98 likes · 22 retweets · 172 bookmarks · 10671 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-02-@0xluffy_eth-790310.md","filePath":"research/tweets/2026-06-02-@0xluffy_eth-790310.md","lastUpdated":1780990164000}'),i={name:"research/tweets/2026-06-02-@0xluffy_eth-790310.md"};function l(p,s,o,r,h,d){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="我连续跑了几个月-hermes-agent-最后发现-99-的人根本没用对-ai-agent-—-0xluffy-eth" tabindex="-1">我连续跑了几个月 Hermes Agent，最后发现：99% 的人根本没用对 AI Agent — @0xluffy_eth <a class="header-anchor" href="#我连续跑了几个月-hermes-agent-最后发现-99-的人根本没用对-ai-agent-—-0xluffy-eth" aria-label="Permalink to &quot;我连续跑了几个月 Hermes Agent，最后发现：99% 的人根本没用对 AI Agent — @0xluffy_eth&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/0xluffy_eth/status/2061641905096790310" target="_blank" rel="noreferrer">https://x.com/0xluffy_eth/status/2061641905096790310</a><strong>作者</strong>：0xluffy_eth（@0xluffy_eth） <strong>發布日期</strong>：2026-06-02 <strong>收錄日期</strong>：2026-06-02 <strong>類型</strong>：Twitter Article <strong>統計</strong>：98 likes · 22 retweets · 172 bookmarks · 10671 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>大多数人还在把 AI Agent 当聊天机器人用。 我连续几个月 24 小时跑 Hermes Agent，测试了安装、模型、任务、Dashboard、多 Agent、记忆、自我改进和安全设置。 看完这篇，你会知道怎么把它变成一个真正能替你干活的 AI 员工。</p><p>【先说结论】</p><p>Hermes Agent 最恐怖的地方，不是它能执行任务。 而是它会记住你是谁、你做过什么、你怎么工作，并且每完成一次任务，就把经验写进自己的技能库。</p><p>ChatGPT 和 Claude 是&quot;每次重新认识你&quot;。 Hermes 是&quot;越用越懂你&quot;。 这就是差距。</p><p>【它是谁】</p><p>Hermes Agent 是 Nous Research 做的 24/7 自主 AI 员工。 它不是普通聊天框。 你给它目标，它会拆任务、执行、复盘、沉淀经验，下次再做同类任务时，直接沿用之前学到的方法。</p><p>它真正强在 3 件事：</p><ol><li>记忆存在你电脑里</li><li>每次任务后会自我改进</li><li>所有历史会话都能被召回</li></ol><p>记忆不是黑箱，也不是云端数据库。 它以 markdown 文件存在本地，你可以打开、修改、删除。 所以你不是在&quot;用一个工具&quot;。 你是在训练一个越来越像你助理的人。</p><p>【比谁强】</p><p>Hermes 更像 Chief of Staff。 Claude Code / Codex 更像深度编程搭子。 OpenClaw 更像早期强，但现在越来越臃肿的 Agent 框架。</p><p>Hermes 的优势很明显：更轻、更快、更新不容易炸。 还自带多 Agent Kanban、Nous Portal、166 个技能、20+ 消息平台。</p><p>日常任务、研究、文档、运营、内容、电脑管理，用 Hermes。 深度写代码、大型项目、复杂测试，用 Claude Code 或 Codex。 不要混着用。它们不是替代关系，是分工关系。</p><p>【怎么安装】</p><p>macOS / Linux / WSL2 / Android Termux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.sh</span></span></code></pre></div><p>Windows PowerShell：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (irm </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.ps1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>装完直接输入 <code>hermes</code>，它会带你选模型、配置消息平台。 如果之前装过 OpenClaw：<strong>不要导入记忆</strong>，重新开始更干净，两个 Agent 独立记忆长期更稳定。</p><p>【模型选择】</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>复杂推理 / 长任务 / 商业判断   → Claude Opus 4 / Sonnet 4（重度使用每月可能几百美元）</span></span>
<span class="line"><span>新手 / 日常编码 / 原型          → GPT-5.5（可吃现有 ChatGPT 订阅）</span></span>
<span class="line"><span>省钱 / 长时间自主任务           → Qwen 3.7 Max</span></span>
<span class="line"><span>X 内容研究                      → Grok</span></span>
<span class="line"><span>不想管理 API Key                → Nous Portal</span></span></code></pre></div><p>随时切换：<code>hermes model</code>（不用重装，不用改代码）</p><p>【消息平台】</p><p>直接用 Telegram。Hermes 支持 20+ 平台，但 Telegram 最适合 Agent：BotFather 配置快、手机体验好、消息稳定。 在 Telegram 创建 Bot，把 token 填进 Hermes，5 分钟结束。 然后你就能在手机上远程指挥你的 AI 员工。</p><p>【第一天】</p><p>第一条消息发这个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的基本信息：</span></span>
<span class="line"><span>名字：[你的名字]</span></span>
<span class="line"><span>我在做：[你的业务/职业]</span></span>
<span class="line"><span>我现在的项目：[项目列表]</span></span>
<span class="line"><span>未来 3-6 个月目标：[具体目标]</span></span>
<span class="line"><span>我的工作习惯：[偏好/时间/格式要求]</span></span>
<span class="line"><span>我的时区：[你的时区]</span></span></code></pre></div><p>跳过这步，Hermes 就是在盲干。认真写，它后面所有主动任务都会围绕你的目标过滤。</p><p>【定时任务】</p><p>Hermes 最像员工的地方是 cron job（定时自动任务）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每天凌晨 2 点，帮我自动做一个小工具、小页面或小系统。</span></span>
<span class="line"><span>要求是：节省我的时间，推进我的目标，最好能让我第二天早上看到时有惊喜。</span></span></code></pre></div><p>你睡觉的时候，它真的会继续干活。这才是 Agent 和聊天机器人的分水岭。 <strong>聊天机器人等你问。Agent 主动推进。</strong></p><p>【核心命令】</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [任务描述]    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动自主任务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 查看状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pause</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 暂停</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 继续</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 结束当前目标</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/subgoal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [补充条件] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 中途追加条件</span></span></code></pre></div><p>提高 max_turns（研究/报告设 20，代码重构设 50，不要乱设更高，每一轮都烧 token）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hermes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goals.max_turns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span></code></pre></div><p>【看板才是核心】</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hermes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 进入 localhost:9119</span></span></code></pre></div><p><strong>99% 的人第一眼去看模型，错了。先看 Skills 和 Kanban。</strong></p><ul><li><strong>Models</strong>：切模型</li><li><strong>Cron</strong>：定时任务</li><li><strong>Skills</strong>：它学会了什么</li><li><strong>Plugins</strong>：浏览器、爬取、电脑控制</li><li><strong>Profiles</strong>：多 Agent</li><li><strong>Kanban</strong>：最重要的任务中控台</li></ul><p>Kanban 状态流：<code>Triage → To-Do → Ready → In Progress → Blocked → Done</code> 每天早上把待办写进去，能交给 AI 的全部丢进 Triage，然后走人。</p><p>【常用场景（8 个）】</p><ol><li><strong>每日学习教练</strong>：丢 YouTube transcript → 提炼核心概念 → 每天 8 点提醒 + 测试</li><li><strong>文件和电脑管理</strong>：配合 Tailscale，跨设备移动文件，不用 SSH/网盘</li><li><strong>历史会话召回</strong>：FTS5 全文搜索 + LLM 总结，找上月讨论过的商业点子</li><li><strong>X 内容工作流</strong>：xurl 技能研究 X 讨论 → 生成 → 发布（先人工审核 5-7 次再开半自动）</li><li><strong>自定义工作台</strong>：Mission Control = 选题池 + 记忆 wiki + 文档库 + 任务状态</li><li><strong>原型构建</strong>：gym 里想到产品点子 → Telegram 发 → 回家看到 landing page</li><li><strong>商业顾问</strong>：结合你的业务/目标/历史偏好给判断，不是通用框架</li><li><strong>睡前长任务</strong>：/goal 竞品调研 → 第二天醒来拿接近人工分析师水平的初稿</li></ol><p>【多 Agent 分工】</p><p>一个 Profile = 一个独立 Agent（独立记忆/技能/模型/角色）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Chief of Staff  → 汇总、派活、每天早上发简报</span></span>
<span class="line"><span>Head of Research → 找资料、盯竞品、监控 X</span></span>
<span class="line"><span>Head of Content → 写内容、改写、拆长文、维护选题库</span></span>
<span class="line"><span>DevOps Engineer → 脚本、部署、本地系统、自动化</span></span></code></pre></div><p>各 Agent 独立成长，由 Chief of Staff 汇总给你。</p><p>【真正优势：自我改进】</p><p>循环：你给任务 → 它执行 → 复盘哪里做对/错/下次怎么更快 → 经验写入 <code>~/.hermes/skills/</code> → 下次直接调用</p><p>区别在于：</p><ul><li>它的经验可以被你打开</li><li>它的技能可以被你编辑</li><li>它的记忆可以被你删除</li></ul><p>没有黑箱。</p><p>【安全问题】</p><p>个人使用安全风险被夸大了。它主要做你明确要求的事。</p><p>最低限度的安全规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># soul.md 写死</span></span>
<span class="line"><span>Never send money to anyone without explicit confirmation.</span></span></code></pre></div><p><strong>不要让它</strong>：自动转账、自动删除重要文件、自动发布高风险内容。</p><p>生产环境：Bitwarden Secrets Manager（管真实密钥）+ iron-proxy（给 Agent 代理 token，沙箱里拿不到真正 API Key）。 个人用户：主电脑安装，谨慎授权，危险操作人工确认，够了。</p><p>【Hermes 入门框架】</p><ol><li>先告诉 Hermes 你是谁</li><li>第一周只跑低风险任务</li><li>Telegram 作为主入口</li><li>GPT-5.5 起步，复杂任务再上 Claude</li><li>每天至少建一个 cron job</li><li>用 /goal 跑长任务</li><li>Dashboard 先看 Skills 和 Kanban</li><li>Profiles 拆成多个角色</li><li>自动发布前先人工审核 5-7 次</li><li>在 soul.md 写清楚安全底线</li></ol><p>【真实判断】</p><p>AI Agent 的瓶颈已经不是模型，而是<strong>记忆、自我改进和信任</strong>。Hermes 正好打中这 3 个点。</p><p>第 1 天，它不了解你。 第 30 天，它知道你的项目、风格、常用工具。 第 180 天，它知道你怎么思考、哪些任务每天重复、哪些流程最省时间。</p><p>真正的 AI Agent 不是更会聊天，而是能持续积累工作经验。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：作者連幾個月 24h 跑 Hermes Agent 的完整使用指南，核心主張是 Agent 的差異化在「記憶＋自我改進＋信任」三角，而非模型能力，cron job 是 Agent 與聊天機器人的分水嶺。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Hermes vs. ChatGPT/Claude 根本差異</strong>：後者每次重新認識，Hermes 越用越懂你，任務後經驗寫入 <code>~/.hermes/skills/</code></li><li><strong>cron job 是分水嶺</strong>：睡覺時 Agent 繼續工作，定時任務讓它成為真正的員工而非聊天框</li><li><strong>Dashboard 正確使用順序</strong>：先看 Skills 和 Kanban，不是模型；Kanban Triage 是任務中控台</li><li><strong>多 Agent 分工哲學</strong>：Chief of Staff / Research / Content / DevOps 各自獨立成長，再由 CoS 匯總</li><li><strong>安全底線</strong>：soul.md 寫死不自動轉帳/刪除/高風險發布；生產環境加 Bitwarden + iron-proxy</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Hermes Agent：Nous Research，localhost:9119，166 內建 skills，20+ 消息平台</li><li>安裝：curl install.sh（macOS/Linux/WSL2/Android Termux）</li><li>核心命令：<code>/goal</code>、<code>/subgoal</code>、<code>hermes model</code>、<code>hermes config set goals.max_turns</code></li><li>max_turns 建議：研究/報告 20，代碼重構 50</li><li>記憶路徑：<code>~/.hermes/skills/</code>（markdown，FTS5 全文搜索 + LLM 摘要）</li><li>安全工具：Bitwarden Secrets Manager + iron-proxy（生產環境）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>自我改進機制描述很吸引（「越用越懂你」），但無量化數據，30/180 天差異為作者主觀描述</li><li>文章明確說 Hermes 與 Claude Code「不要混著用，是分工關係」—— 對 Claude Code 重度用戶，整合價值有限</li><li>模型選擇部分（GPT-5.5 起步）有時效性問題，且與現有 workspace 的 Claude 優先策略衝突</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>5/10</td><td>Hermes 是獨立框架，文章明確說與 Claude Code 分工不混用，直接套用有限</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>記憶＋自我改進＋信任三角框架、cron job 定時任務哲學有新意</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>基於作者幾個月個人使用，無量化指標，高度主觀</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>安裝/命令/安全配置完整，但缺乏深度實現細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>Hermes 特定，但記憶設計哲學（本地 markdown + FTS5）可借鑑</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.7/10</strong></td><td>5×0.3+7×0.2+5×0.2+6×0.15+6×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（僅歸檔） <strong>理由</strong>：分數 ≤ 6，且文章明確定位 Hermes 為 Claude Code 的分工替代而非補充，對現有 workspace 直接可行動性低。</p>`,81)])])}const k=a(i,[["render",l]]);export{c as __pageData,k as default};
